      "target_shift": "从计数总数改成带权或分布统计",
      "new_obligation": "定义权重函数、分类统计量和汇总不变量"
    },
    "helpers": [
      {
        "id": "weight_or_statistic_definition",
        "summary": "在原计数对象上定义自然权重或分类统计量。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让计数目标从总数升级为结构化统计。",
        "difficulty_role": "要求算法保留对象的附加统计信息。",
        "prompt_guidance": [
          "权重或统计量必须由原计数对象自身决定。",
          "目标要说明输出总权重、分布或分层结果。"
        ],
        "redlines": [
          "不能只换模数。",
          "不能添加与计数对象无关的权重。"
        ]
      },
