  "constraints": [
    "1 ≤ N ≤ 100,000",
    "1 ≤ Q ≤ 5,000",
    "1 ≤ S_i ≤ E_i ≤ 1,000,000,000",
    "1 ≤ p ≤ 1,000,000,000",
