import sys

def solve(input_str: str) -> str:
    data = input_str.strip().split()
    if not data:
        return "0"
    idx = 0
    N = int(data[idx]); idx += 1
    intervals = []
    for _ in range(N):
        S = int(data[idx]); E = int(data[idx+1]); idx += 2
        intervals.append((S, E))
    Q = int(data[idx]); idx += 1
    queries = []
    for _ in range(Q):
        p = int(data[idx]); t = int(data[idx+1]); idx += 2
        queries.append((p, t))

    # 处理查询：去重并检查冲突
    pos_to_t = {}
    for p, t in queries:
        if p in pos_to_t:
            if pos_to_t[p] != t:
                return "-1"  # 同一位置冲突
        else:
            pos_to_t[p] = t
    # 检查 t 是否超过 N
    for t in pos_to_t.values():
        if t > N:
            return "-1"
    # 构造排序后的位置列表和对应目标
    positions = sorted(pos_to_t.keys())
    M = len(positions)
    targets = [pos_to_t[p] for p in positions]

    # 暴力枚举所有物品保留子集（0~2^N-1）
    max_kept = -1
    for mask in range(1 << N):
        kept_cnt = 0
        cov = [0] * M
        # 计算保留物品的覆盖
        for i in range(N):
            if (mask >> i) & 1:
                kept_cnt += 1
                S, E = intervals[i]
                for j in range(M):
                    if S <= positions[j] <= E:
                        cov[j] += 1
        # 检查是否所有点需求都能被补足
        feasible = True
        for j in range(M):
            if cov[j] > targets[j]:
                feasible = False
                break
        if not feasible:
            continue
        # 计算所需新区间数
        need = 0
        prev = 0
        for j in range(M):
            d = targets[j] - cov[j]
            if d > prev:
                need += d - prev
            prev = d
        # 判断剩余物品是否足够
        if need <= N - kept_cnt:
            if kept_cnt > max_kept:
                max_kept = kept_cnt

    if max_kept == -1:
        return "-1"
    else:
        return str(N - max_kept)

