import sys

def solve(input_str: str) -> str:
    data = input_str.strip().split()
    if not data:
        return "0"
    it = iter(data)
    n = int(next(it))
    intervals = []
    for _ in range(n):
        s = int(next(it))
        e = int(next(it))
        intervals.append((s, e))
    q = int(next(it))
    ans = 0
    for _ in range(q):
        p = int(next(it))
        t = int(next(it))
        # 统计当前位置初始覆盖的物品数量
        cnt = 0
        for s, e in intervals:
            if s <= p <= e:
                cnt += 1
        # 只考虑需要增加覆盖的情况
        if t > cnt:
            ans += t - cnt
    return str(ans)

if __name__ == "__main__":
    input_data = sys.stdin.read()
