def solve(input_str: str) -> str:
    # 解析输入
    data = input_str.strip().split()
    if not data:
        return '0'
    it = iter(data)
    N = int(next(it))
    items = []
    for _ in range(N):
        S = int(next(it))
        E = int(next(it))
        items.append((S, E))
    Q = int(next(it))
    queries = []
    for _ in range(Q):
        p = int(next(it))
        t = int(next(it))
        queries.append((p, t))

    max_need = 0  # 记录所有检查点需要的最大额外物品数
    for p, t in queries:
        # 统计当前检查点被多少物品覆盖
        cnt = 0
        for S, E in items:
            if S <= p <= E:
                cnt += 1
        # 如果已经有不少于t个物品，则认为满足（至少t个）
        if cnt < t:
            need = t - cnt
            if need > max_need:
                max_need = need

    # 需要的额外物品数不能超过物品总数，否则无法实现
    if max_need > N:
        return "-1"
    else:
        return str(max_need)

