def solve(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    N = int(lines[0].strip())
    items = []
    idx = 1
    for _ in range(N):
        s, e = map(int, lines[idx].strip().split())
        items.append((s, e))
        idx += 1
    Q = int(lines[idx].strip())
    idx += 1
    queries = []
    for _ in range(Q):
        p, t = map(int, lines[idx].strip().split())
        queries.append((p, t))
        idx += 1

    ans = 0
    for p, t in queries:
        cnt = 0
        for s, e in items:
            if s <= p <= e:
                cnt += 1
        need = t - cnt
        if need < 0:
            need = 0
        if need > ans:
            ans = need
    return str(ans)

