        "target": "expected_value",
        "requires_solution": false
      },
      "invariant": {
        "invariants": [
          {
            "name": "subtree_size_aggregation",
            "description": "The size of the subtree rooted at any node can be stably computed by aggregating the sizes of its children in a post-order traversal, always yielding 1 plus the sum of child subtree sizes, regardless of traversal order.",
            "properties": {},
            "evidence_source": "solution_code"
