input_structure: {
  "type": "tree_and_target_array",
  "length": {"min": 1, "max": 100000},
  "properties": {
    "tree_rooted_at_1": true,
    "acyclic": true,
    "connected": true
  },
  "additional_fields": {
    "target_expectations": {
      "description": "Array t of length n with t_i being target expected starting time for node i. t_1 must be 1.0 (root expectation is fixed).",
      "type": "float_array"
    }
  }
}

core_constraints: {
  "constraints": [
    {
      "name": "valid_operation_definition",
      "description": "An operation consists of selecting a non-root node v and a new parent p (p != v and p not in the subtree of v) and setting parent[v] = p. The resulting graph must remain a tree rooted at 1."
    },
    {
      "name": "expectation_matching_target",
      "description": "After operations, for each node i, the expected starting time E[i] computed via the random DFS process must satisfy |E[i] - t_i| <= 1e-6."
    }
  ]
}

objective: {
  "type": "minimization_and_construction",
  "description": "Find the minimum number of valid operations (parent changes) such that the resulting tree's expected starting times match the target array within absolute error 1e-6. Output the minimum k followed by k lines each describing v and new_parent. If impossible, output -1."
}

invariant: {
  "invariants": [
    {
      "name": "expectation_recurrence_holds",
      "description": "For any tree (rooted at 1) and any node v, E[1]=1 and E[v] = E[parent(v)] + 1 + (sum_{sibling s} size(s) - size(v))/2, where size(w) is the number of nodes in the subtree of w. This holds before and after any sequence of valid operations."
    },
    {
      "name": "operation_effect_quantification",
      "description": "Changing parent of v from p to p' changes subtree sizes along the paths from p and p' to root, and adjusts E values for v and its descendants. The change in E[u] for u in subtree of v is a function of the size differences and ancestral expectations."
    },
    {
      "name": "minimality_lower_bound",
      "description": "A lower bound on the number of operations can be derived from mismatches between original E and target t; each operation can resolve at most a constant number of independent mismatches under certain structural conditions."
    }
  ]
}

difficulty: "hard"

algorithmic_delta_claim: {
  "seed_solver_core": "Compute subtree sizes via post-order traversal; then compute expected starting times through a top-down pass using linear recurrence based on parent expectation and sibling subtree sizes.",
  "reusable_subroutines": "Subtree size calculation, expectation propagation algorithm, tree traversal orders.",
  "new_solver_core": "Identify nodes with expectation mismatches; analyze how changing parents affects expectations; formulate the problem as a minimum cover or matching problem on dependencies; derive a lower bound and construct an optimal sequence using combinatorial properties of the recurrence (e.g., independence of siblings' contributions).",
  "new_proof_obligation": "Prove that the constructed sequence achieves the minimum number of operations, possibly by showing that the mismatch vector has a certain rank and each operation can reduce it by at most 1, and that the constructed sequence attains this reduction.",
  "why_direct_reuse_fails": "The forward solver only computes expectations from a fixed tree; it does not provide any mechanism to select or minimize changes to meet a target array, requiring a fundamentally different optimization approach."
}

