        "target_expectations": {
          "type": "array of size n",
          "description": "目标期望起始时间数组 t[1..n]，t[1] 必须为 1.0 (因为根起始时间固定为1)，其余值为浮点数"
        }
      }
    },
    "core_constraints": {
      "constraints": [
        {
          "name": "parent_swap_operation",
          "description": "允许进行如下操作：选择一个非根节点 i (i != 1)，将其父节点改为另一个节点 j (j != i，且 j 不能是 i 的后代，以保证不产生环)，操作后图仍为一棵以 1 为根的有根树。每次操作计数为 1。",
          "properties": {
            "operation_cost": 1,
            "legality_check": "j not in subtree of i, and i != j"
          }
        },
        {
          "name": "target_feasibility",
          "description": "必须找到一系列合法操作，使得最终树上按原题正向算法计算出的期望时间数组与输入的目标数组每个位置绝对误差不超过 1e-6。若不可能，输出 -1（或表示不可行）。",
          "properties": {}
        }
      ]
    },
