import sys
from collections import deque, defaultdict

def parse_input(input_str: str):
    data = input_str.strip().split()
    if not data:
        return None
    n = int(data[0])
    idx = 1
    parents_init = [0] * (n + 1)  # 1-based, index 0 unused
    parents_init[1] = 0
    if n > 1:
        for i in range(2, n + 1):
            parents_init[i] = int(data[idx])
            idx += 1
    t = [0.0] * (n + 1)
    for i in range(1, n + 1):
        t[i] = float(data[idx])
        idx += 1
    return n, parents_init, t

def compute_expectation(parents, n):
    # 构建孩子列表
    children = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        p = parents[i]
        children[p].append(i)

    size = [0] * (n + 1)
    # 后序遍历计算 size
    order = []
    stack = [1]
    while stack:
        u = stack.pop()
        order.append(u)
        for v in children[u]:
            stack.append(v)
    for u in reversed(order):
        size[u] = 1
        for v in children[u]:
            size[u] += size[v]

    E = [0.0] * (n + 1)
    E[1] = 1.0
    # BFS 计算期望
    q = deque([1])
    while q:
        u = q.popleft()
        # 计算 S = 所有子节点 size 之和
        S = sum(size[v] for v in children[u])
        for v in children[u]:
            E[v] = E[u] + 1.0 + 0.5 * (S - size[v])
            q.append(v)
    return E

def is_descendant(i, j, parents, n):
    # 检查 j 是否在 i 的子树中（即从 i 出发能否到达 j）
    children = [[] for _ in range(n + 1)]
    for node in range(2, n + 1):
        p = parents[node]
        children[p].append(node)
    stack = [i]
    visited = set()
    while stack:
        u = stack.pop()
        if u == j:
            return True
        if u not in visited:
            visited.add(u)
            for v in children[u]:
                stack.append(v)
    return False

def solve(input_str: str) -> str:
    parsed = parse_input(input_str)
    if parsed is None:
        return "-1"
    n, parents_init, t = parsed

    if n == 1:
        if abs(1.0 - t[1]) <= 1e-6:
            return "0"
        else:
            return "-1"

    # 初始期望检查
    E_init = compute_expectation(parents_init, n)
    if all(abs(E_init[k] - t[k]) <= 1e-6 for k in range(1, n + 1)):
        return "0"

    # BFS
    start_state = tuple(parents_init[2:])  # 不包含根
    visited = set()
    visited.add(start_state)
    queue = deque()
    queue.append((start_state, 0))

    while queue:
        state, dist = queue.popleft()
        parents = [0] * (n + 1)
        parents[1] = 0
        for i, p in enumerate(state, start=2):
            parents[i] = p

        # 尝试每个非根节点
        for i in range(2, n + 1):
            old_p = parents[i]
            for j in range(1, n + 1):
                if j == i or j == old_p:
                    continue
                if is_descendant(i, j, parents, n):
                    continue  # j 是 i 的后代，不合法
                new_parents = parents.copy()
                new_parents[i] = j
                new_state = tuple(new_parents[2:])
                if new_state not in visited:
                    # 计算期望
                    E_new = compute_expectation(new_parents, n)
                    if all(abs(E_new[k] - t[k]) <= 1e-6 for k in range(1, n + 1)):
                        return str(dist + 1)
                    visited.add(new_state)
                    queue.append((new_state, dist + 1))
    return "-1"

if __name__ == "__main__":
    # 可以从标准输入读取，但为了通用性，solve 接受字符串
    pass

